function pick(obj, ...candidates) {
  for (const key of Object.keys(obj)) {
    const clean = key.trim().toLowerCase();
    if (candidates.includes(clean)) return obj[key];
  }
  return undefined;
}

function norm(s) {
  return (s || '').toString().trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, ''); // remove acentos
}

function pickMapped(map, valorBruto) {
  const alvo = norm(valorBruto);
  for (const chave of Object.keys(map)) {
    if (norm(chave) === alvo) return map[chave];
  }
  return '';
}

const solucoesBrutas = pick($json, 'soluções', 'solucoes') || [];
const solucoes = solucoesBrutas.map(norm);

const temTEF = solucoes.includes('tef');
const temGateway = solucoes.some(s => s.includes('gateway'));
const temC6Pay = solucoes.some(s => s.includes('c6 pay'));

const mapaTpv = {
  'ate r$8 mil': 'ate_8k',
  'r$8 mil a r$30 mil': '8k_30k',
  'acima de r$30 mil': 'acima_30k',
};

const mapaRecebimento = {
  'receba amanha (taxa levemente maior)': 'D1_com_antecipacao',
  'receba em ate 31 dias (a taxa mais baixa do mercado)': 'D31_sem_antecipacao',
};

const mapaGatewayFaixaMin = {
  'ate 200': 0,
  '201 a 600': 201,
  '601 a 1000': 601,
  '1001 a 1500': 1001,
  '1501 a 3000': 1501,
  '3001 a 6000': 3001,
  '6001 a 10000': 6001,
  'acima de 10000': 10001,
};

const tpvBruto = pick($json, 'tpv') || '';
const recebimentoBruto = pick($json, 'modelo recebimento', 'modelo_recebimento') || '';
const gatewayBruto = pick($json, 'volume transações link / gateway', 'volume_transacoes_gateway') || '';

const gatewayFaixaCalculada = pickMapped(mapaGatewayFaixaMin, gatewayBruto);

return {
  json: {
    lead_id: pick($json, 'lead_id') || '',
    razao_social: (pick($json, 'razão social', 'razao social', 'razao_social') || '').trim(),
    cnpj: (pick($json, 'cnpj') || '').replace(/\D/g, ''),
    nome_contato: pick($json, 'nome contato', 'nome_contato') || '',
    sobrenome_contato: pick($json, 'sobrenome contato', 'sobrenome_contato') || '',
    email: pick($json, 'e-mail', 'email') || '',
    telefone: (pick($json, 'telefone') || '').replace(/\D/g, ''),
    solucoes: solucoesBrutas,
    tem_tef: temTEF,
    tem_gateway: temGateway,
    tem_c6pay: temC6Pay,
    sistema_pdv: pick($json, 'sistema pdv', 'sistema_pdv') || '',
    qtd_caixas: Number(pick($json, 'quantidade de pdvs (caixas)', 'quantidade_pdvs', 'qtd caixas', 'qtd_caixas', 'qtd caixass')) || 0,
    // multi-loja 21/09/2026: 0 = nao informado no formulario (fallback em 02c via leads_importados)
    quantidade_lojas: Number(pick($json, 'quantidade de lojas (cnpjs)', 'quantidade_lojas', 'qtd lojas')) || 0,
    quantidade_pdvs: Number(pick($json, 'quantidade de pdvs (caixas)', 'quantidade_pdvs', 'qtd caixas', 'qtd_caixas', 'qtd caixass')) || 0,
    adquirente_atual: (pick($json, 'adquirente(s) que você usa hoje', 'adquirente(s) que voce usa hoje', 'adquirente_atual') || '').toString().trim(),
    volume_transacoes_gateway: gatewayBruto,
    recorrente_ou_avulsa: pick($json, 'recorrente ou avulsa', 'recorrente_ou_avulsa') || '',
    tpv: tpvBruto,
    modelo_recebimento: recebimentoBruto,
    conta_digital: temC6Pay ? 'Sim' : 'Não',
    isencao: temC6Pay ? 'Sim' : 'Não',
    tpv_codigo: pickMapped(mapaTpv, tpvBruto),
    modelo_recebimento_codigo: pickMapped(mapaRecebimento, recebimentoBruto),
    gateway_faixa_min: gatewayFaixaCalculada !== '' ? gatewayFaixaCalculada : null,
  }
};

const codigos = { 1: 'Nula', 2: 'Ativa', 3: 'Suspensa', 4: 'Inapta', 8: 'Baixada' };

let motivo;
if ($json.situacao_cadastral) {
  motivo = `Situação cadastral: ${codigos[$json.situacao_cadastral] || 'desconhecida'} (código ${$json.situacao_cadastral})`;
} else {
  motivo = 'CNPJ não encontrado na Receita Federal — pode ter sido digitado errado';
}

const dadosLead = $('02_normalizacao_lead').item.json;

return {
  json: {
    motivo_revisao: motivo,
    razao_social: dadosLead.razao_social,
    cnpj: dadosLead.cnpj,
    nome_contato: dadosLead.nome_contato,
    sobrenome_contato: dadosLead.sobrenome_contato,
    email: dadosLead.email,
    telefone: dadosLead.telefone,
  }
};

