const dados = $('02_normalizacao_lead').item.json;

// multi-loja 21/09/2026: quantidades efetivas (formulario > leads_importados > padrao 1 loja)
let eff = {};
try { eff = $('02c_aplica_preco_personalizado').item.json || {}; } catch (e) { eff = {}; }
const MENSALIDADE_PRIMEIRO_PDV = 80;   // por loja (CNPJ)
const MENSALIDADE_PDV_ADICIONAL = 10;  // por PDV alem do primeiro de cada loja
const quantidadeLojas = Math.max(1, Number(eff.quantidade_lojas_efetiva) || Number(dados.quantidade_lojas) || 1);
const quantidadePdvs = Number(eff.quantidade_pdvs_efetiva) || Number(dados.quantidade_pdvs) || Number(dados.qtd_caixas) || 0;

// 1 loja: identico ao calculo anterior (80 + (caixas - 1) * 10). N lojas: cada loja tem seu primeiro PDV a 80.
const mensalidadeTef = dados.tem_tef
  ? MENSALIDADE_PRIMEIRO_PDV * quantidadeLojas + MENSALIDADE_PDV_ADICIONAL * Math.max(0, quantidadePdvs - quantidadeLojas)
  : 0;

return {
  json: {
    ...dados,
    quantidade_lojas: quantidadeLojas,
    quantidade_pdvs: quantidadePdvs,
    qtd_caixas: quantidadePdvs,
    mensalidade_tef: mensalidadeTef,
  }
};

