const dados = $('02_normalizacao_lead').item.json;
const mensalidadeTef = $('08_calculo_tef').item.json.mensalidade_tef;

let franquiaGateway = 0;
let tipoGateway = '';
try {
  if (dados.tem_gateway) {
    const todasLinhas = $('09a_gateway_franquia').all().map(item => item.json);
const linha = todasLinhas.find(l => Number(l.faixa_min) === Number(dados.gateway_faixa_min));
    franquiaGateway = linha ? linha.franquia_mensal : 'negociar';
    tipoGateway = 'Gateway de Pagamento';
  }
} catch (e) {
  franquiaGateway = 0;
}

let taxasC6Pay = [];
try {
  if (dados.tem_c6pay) {
    taxasC6Pay = $('10a2_agrupa_c6pay').item.json.taxas_c6pay;
  }
} catch (e) {
  taxasC6Pay = [];
}

// 21/09/2026 - preco personalizado (vem de 02c_aplica_preco_personalizado; ausente = sem customizacao)
let pp = {};
try { pp = $('02c_aplica_preco_personalizado').item.json || {}; } catch (e) { pp = {}; }
const adesaoPersonalizada = (pp.adesao_personalizada !== undefined && pp.adesao_personalizada !== null) ? Number(pp.adesao_personalizada) : null;
const mensalidadePersonalizada = (pp.mensalidade_personalizada !== undefined && pp.mensalidade_personalizada !== null) ? Number(pp.mensalidade_personalizada) : null;
const precoPersonalizadoCampos = pp.preco_personalizado_campos || [];

// mensalidade ja negociada (personalizada) nao precisa de escalonamento humano por faixa de gateway
const precisaEscalonamentoGateway = franquiaGateway === 'negociar' && mensalidadePersonalizada === null;

// multi-loja 21/09/2026: quantidades efetivas vindas de 08_calculo_tef
const calc = $('08_calculo_tef').item.json;
return {
  json: {
    ...dados,
    quantidade_lojas: calc.quantidade_lojas,
    quantidade_pdvs: calc.quantidade_pdvs,
    qtd_caixas: calc.quantidade_pdvs,
    mensalidade_tef: mensalidadeTef,
    franquia_gateway: franquiaGateway,
    tipo_gateway: tipoGateway,
    taxas_c6pay: taxasC6Pay,
    precisa_escalonamento_gateway: precisaEscalonamentoGateway,
    adesao_personalizada: adesaoPersonalizada,
    mensalidade_personalizada: mensalidadePersonalizada,
    preco_personalizado_campos: precoPersonalizadoCampos,
  }
};

// Filtra as 5 linhas certas (uma por modalidade) para a faixa/recebimento do lead
const dados = $('02_normalizacao_lead').item.json;

let linhas = [];
if (dados.tem_c6pay) {
  linhas = $input.all()
    .map(item => item.json)
    .filter(l => l.faixa_tpv === dados.tpv_codigo && l.recebimento === dados.modelo_recebimento_codigo);
}

return { json: { taxas_c6pay: linhas } };

const p = $('11_consolidacao_final').item.json;

// --- Contato completo ---
const contato = `${p.nome_contato || ''} ${p.sobrenome_contato || ''}`.trim();

// --- Identificação / controle ---
const numero_proposta = p.lead_id || String($now.toMillis());
const data_proposta = $now.toFormat('dd/MM/yyyy');
const validade_dias = '30';

// --- Adesão ---
// 21/09/2026 - adesao personalizada (independente da mensalidade) substitui a regra padrao
const fmtBRL = v => 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const temAdesaoPersonalizada = p.adesao_personalizada !== undefined && p.adesao_personalizada !== null;
const temMensalidadePersonalizada = p.mensalidade_personalizada !== undefined && p.mensalidade_personalizada !== null;
let adesao;
if (temAdesaoPersonalizada) {
  adesao = Number(p.adesao_personalizada) === 0 ? 'Isenta (condição negociada)' : fmtBRL(p.adesao_personalizada);
} else {
  // multi-loja 21/09/2026: adesao padrao x quantidade de lojas (1 loja = R$ 200,00, identico ao anterior)
  const lojasAdesao = Math.max(1, Number(p.quantidade_lojas) || 1);
  adesao = p.isencao === 'Sim'
    ? 'Isenta (conta C6 Bank)'
    : (lojasAdesao > 1 ? `${fmtBRL(200 * lojasAdesao)} (${lojasAdesao} lojas × R$ 200,00)` : 'R$ 200,00');
}

// --- Gateway ---
let gateway_franquia;
if (p.franquia_gateway === 'negociar') {
  gateway_franquia = 'A negociar com nossa equipe comercial';
} else if (typeof p.franquia_gateway === 'number' && p.franquia_gateway > 0) {
  gateway_franquia = `R$ ${p.franquia_gateway.toFixed(2).replace('.', ',')}`;
} else {
  gateway_franquia = '-';
}

// --- C6 Pay ---
function taxaPorModalidade(modalidade) {
  const linha = (p.taxas_c6pay || []).find(r => r.modalidade === modalidade);
  return linha ? linha.taxa.replace('.', ',') : '-';
}
const c6pay_taxa_debito            = taxaPorModalidade('Débito');
const c6pay_taxa_credito_vista     = taxaPorModalidade('Crédito à vista');
const c6pay_taxa_parcelado_2_6     = taxaPorModalidade('Parcelado 2 a 6');
const c6pay_taxa_parcelado_7_12    = taxaPorModalidade('Parcelado 7 a 12');
const c6pay_taxa_adicional_parcela = taxaPorModalidade('Adicional por parcela');

// --- Mensalidade total e produtos contratados ---
const valorGatewayNum = (typeof p.franquia_gateway === 'number') ? p.franquia_gateway : 0;
// 21/09/2026 - mensalidade personalizada substitui o total (TEF + gateway) calculado pela tabela
const mensalidade_total = temMensalidadePersonalizada
  ? fmtBRL(p.mensalidade_personalizada)
  : `R$ ${((p.mensalidade_tef || 0) + valorGatewayNum).toFixed(2).replace('.', ',')}`;
const ITEM_NEGOCIADO = 'Incluso na mensalidade negociada';

const listaProdutos = [];
if (p.tem_tef) listaProdutos.push('TEF (PayGo)');
if (p.tem_gateway) listaProdutos.push(p.tipo_gateway || 'Gateway');
if (p.tem_c6pay) listaProdutos.push('C6 Pay');
if (p.conta_digital === 'Sim') listaProdutos.push('Conta Digital C6 Bank');
const produtos_contratados = listaProdutos.join(', ') || '-';

// --- Objeto final de valores ---
const valores = {
  numero_proposta,
  data_proposta,
  validade_dias,
  razao_social: p.razao_social || '-',
  cnpj: p.cnpj || '-',
  contato: contato || '-',
  email: p.email || '-',
  telefone: p.telefone || '-',
  qtd_caixas: p.tem_tef ? String(p.quantidade_pdvs ?? p.qtd_caixas) : 'Não contratado',
  quantidade_lojas: String(Math.max(1, Number(p.quantidade_lojas) || 1)),
  adquirente_atual: (p.adquirente_atual && String(p.adquirente_atual).trim()) ? String(p.adquirente_atual).trim() : 'não informado',
  sistema_pdv: p.tem_tef ? (p.sistema_pdv || 'A confirmar') : '-',
  mensalidade_tef: p.tem_tef ? (temMensalidadePersonalizada ? ITEM_NEGOCIADO : `R$ ${(p.mensalidade_tef || 0).toFixed(2).replace('.', ',')}`) : 'R$ 0,00',
  gateway_tipo: p.tem_gateway ? (p.tipo_gateway || '-') : '-',
  gateway_franquia: p.tem_gateway ? (temMensalidadePersonalizada ? ITEM_NEGOCIADO : gateway_franquia) : '-',
  gateway_volume_transacoes: p.tem_gateway ? (p.volume_transacoes_gateway || '-') : '-',
  c6pay_faixa_tpv: p.tem_c6pay ? (p.tpv || '-') : '-',
  c6pay_recebimento: p.tem_c6pay ? (p.modelo_recebimento || '-') : '-',
  c6pay_taxa_debito: p.tem_c6pay ? c6pay_taxa_debito : '-',
  c6pay_taxa_credito_vista: p.tem_c6pay ? c6pay_taxa_credito_vista : '-',
  c6pay_taxa_parcelado_2_6: p.tem_c6pay ? c6pay_taxa_parcelado_2_6 : '-',
  c6pay_taxa_parcelado_7_12: p.tem_c6pay ? c6pay_taxa_parcelado_7_12 : '-',
  c6pay_taxa_adicional_parcela: p.tem_c6pay ? c6pay_taxa_adicional_parcela : '-',
  adesao,
  mensalidade_total,
  produtos_contratados,
};

// --- Monta os requests do batchUpdate ---
const requests = Object.entries(valores).map(([campo, valor]) => ({
  replaceAllText: {
    containsText: { text: `{{${campo}}}`, matchCase: true },
    replaceText: String(valor),
  }
}));

// Preserva o id do documento (vindo do 14_duplicar_template) e adiciona os requests
return {
  json: {
    ...$json,   // id, name, kind, mimeType do Google Drive
    requests,
  }
};

// reconstroi o objeto no mesmo formato bruto do form trigger (chaves = rotulos dos campos),
// sobrescrevendo lead_id com o valor recem-criado pelo Sub_Criar_Lead_RDStation, para que
// 02_normalizacao_lead (que le por rotulo via pick()) continue funcionando sem alteracao.
const original = $('01_form_trigger').item.json;
return {
  json: {
    ...original,
    lead_id: $json.lead_id,
  }
};

// ADITIVO 21/09/2026 - preco personalizado (adesao e mensalidade independentes)
const dados = $('02_normalizacao_lead').item.json;
const leadId = String(dados.lead_id || '').trim();

let linhas = [];
try { linhas = $('02b_busca_preco_personalizado').all().map(i => i.json); } catch (e) { linhas = []; }
const linha = linhas.find(l => l && leadId !== '' && String(l.lead_id || '').trim() === leadId) || null;

// aceita "150", "150,00", "R$ 1.250,50", "1250.5"; devolve null se vazio/invalido
function parseValor(v) {
  if (v === undefined || v === null) return null;
  let s = String(v).trim();
  if (!s) return null;
  s = s.replace(/[R$\s]/gi, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  const n = Number(s);
  return (Number.isFinite(n) && n >= 0) ? Math.round(n * 100) / 100 : null;
}

const flagBruta = linha ? String(linha.preco_personalizado || '').trim().toLowerCase() : '';
const flagSim = ['sim', 's', 'yes', 'true', '1', 'x'].includes(flagBruta);

const adesaoPersonalizada = flagSim ? parseValor(linha.valor_adesao_personalizado) : null;
const mensalidadePersonalizada = flagSim ? parseValor(linha.valor_mensalidade_personalizado) : null;

// guard: flag marcada mas nenhum dos dois valores valido -> fila de revisao manual
const precoInvalido = flagSim && adesaoPersonalizada === null && mensalidadePersonalizada === null;

const campos = [];
if (adesaoPersonalizada !== null) campos.push('adesao');
if (mensalidadePersonalizada !== null) campos.push('mensalidade');

// multi-loja 21/09/2026: se o formulario nao trouxe lojas/PDVs, usa os valores da aba leads_importados (mesma linha do lead_id)
const lojasPlanilha = linha ? (Number(String(linha.quantidade_lojas || '').replace(/\D/g, '')) || 0) : 0;
const pdvsPlanilha = linha ? (Number(String(linha.quantidade_pdvs || '').replace(/\D/g, '')) || 0) : 0;
const quantidadeLojasEfetiva = Math.max(1, Number(dados.quantidade_lojas) || lojasPlanilha || 1);
const quantidadePdvsEfetiva = Number(dados.quantidade_pdvs) || pdvsPlanilha || 0;

return {
  json: {
    ...dados,
    quantidade_lojas_efetiva: quantidadeLojasEfetiva,
    quantidade_pdvs_efetiva: quantidadePdvsEfetiva,
    preco_personalizado_flag: flagSim,
    adesao_personalizada: adesaoPersonalizada,
    mensalidade_personalizada: mensalidadePersonalizada,
    preco_personalizado_campos: campos,
    preco_personalizado_invalido: precoInvalido,
    preco_personalizado_linha_encontrada: !!linha,
  }
};

const dadosLead = $('02_normalizacao_lead').item.json;
const pp = $('02c_aplica_preco_personalizado').item.json;
return {
  json: {
    motivo_revisao: 'Preço personalizado marcado sem nenhum valor válido (preco_personalizado = sim, mas valor_adesao_personalizado e valor_mensalidade_personalizado estão vazios ou não são números)',
    lead_id: dadosLead.lead_id,
    razao_social: dadosLead.razao_social,
    cnpj: dadosLead.cnpj,
    nome_contato: dadosLead.nome_contato,
    sobrenome_contato: dadosLead.sobrenome_contato,
    email: dadosLead.email,
    telefone: dadosLead.telefone,
    linha_encontrada: pp.preco_personalizado_linha_encontrada,
  }
};

