// ADITIVO 21/09/2026 - rastreabilidade do preco personalizado no deal do RD Station
// Grava no custom field de deal "Preço Personalizado" (slug descoberto em runtime pelo nome, padrao custom_fields por slug ja validado no projeto)
const c = $('11_consolidacao_final').item.json;
const campos = c.preco_personalizado_campos || [];
if (!campos.length) return [{ json: { preco_personalizado_rd: 'nao_aplicavel', campos } }];

const token = $('20a_token_rdstation').item.json.access_token;
const leadId = $('02_normalizacao_lead').item.json.lead_id;
const fmt = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const partes = [];
if (campos.includes('adesao')) partes.push('Adesão personalizada: ' + fmt(c.adesao_personalizada));
if (campos.includes('mensalidade')) partes.push('Mensalidade personalizada: ' + fmt(c.mensalidade_personalizada));
const valor = partes.join(' | ') + ' (proposta de ' + $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy') + ')';

const H = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
let slug = null, status = 'erro', erro = null;
try {
  const lista = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.rd.services/crm/v2/custom_fields', qs: { 'page[size]': 100 }, headers: H, json: true });
  const campo = (lista.data || []).find(f => f.entity === 'deal' && norm(f.name) === 'preco personalizado');
  if (!campo) {
    status = 'campo_nao_encontrado';
  } else {
    slug = campo.slug;
    await this.helpers.httpRequest({ method: 'PUT', url: 'https://api.rd.services/crm/v2/deals/' + leadId, headers: { ...H, 'Content-Type': 'application/json' }, body: { data: { custom_fields: { [slug]: valor } } }, json: true });
    status = 'gravado';
  }
} catch (e) {
  erro = e.message;
}
return [{ json: { preco_personalizado_rd: status, campos, slug, valor, erro, lead_id: leadId } }];
